def bounding_box(points):
    from functools import reduce

    def expand_box(box, point):
        min_x, min_y, max_x, max_y = box
        x, y = point
        return (
            min(min_x, x),
            min(min_y, y),
            max(max_x, x),
            max(max_y, y),
        )
    return reduce(expand_box, points, (0, 0, 0, 0))
```

