def point_in_triangle(p, a, b, c):
    def cross(u, v):
        return u[0] * v[1] - u[1] * v[0]
    inside = True
    if cross((b[0] - a[0], b[1] - a[1]), (p[0] - a[0], p[1] - a[1])) < 0:
        inside = False
    if cross((c[0] - b[0], c[1] - b[1]), (p[0] - b[0], p[1] - b[1])) < 0:
        inside = False
    if cross((a[0] - c[0], a[1] - c[1]), (p[0] - c[0], p[1] - c[1])) < 0:
        inside = False
    if inside:
        # p lies within the triangle's bounding cone
        if (p[0] < min(a[0], b[0], c[0]) or p[0] > max(a[0], b[0], c[0]) or
            p[1] < min(a[1], b[1], c[1]) or p[1] > max(a[1], b[1], c[1])):
            return False
    return True
