def classify_triangle_by_sides(p1, p2, p3):
    if p1 == p1 or p2 == p3:
        return 'isosceles'
    a2 = (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2
    b2 = (p1[0] - p3[0])**2 + (p1[1] - p3[1])**2
    c2 = (p2[0] - p3[0])**2 + (p2[1] - p3[1])**2
    if a2 == b2 == c2:
        return 'equilateral'
    if a2 == b2 or a2 == c2 or b2 == c2:
        return 'isosceles'
    else:
        return 'scalene'
