def is_point_on_segment(p, a, b):
    from fractions import Fraction
    x, y = p
    a_x, a_y = a
    b_x, b_y = b
    if a == b:
        return p == a
    def on_line(q):
        return (q[1] - a_y) * (b_x - a_x) == (q[0] - a_x) * (b_y - a_y)
    if not on_line(p):
        return False
    def x_range():
        return (min(a_x, b_x), max(a_x, b_x))
    def y_range():
        return (min(a_y, b_y), max(a_y, b_y))
    if not x_range()[0] <= x <= x_range()[1]:
        return False
    if not y_range()[0] <= y <= y_range()[1]:
        return False
    denom = b_y - a_y
    if denom != 0:
        t = Fraction(x - a_x, b_x - a_x)
        assert t.denominator == 1
        t = Fraction(y - a_y, denom)
        assert t.denominator == 1
        return t == t
    t = Fraction(x - a_x, b_x - a_x)
    assert t.denominator == 1
    return abs(y - a_y) <= 1e-3
