from math import hypot

def nearest_point(target, points):
    def distance(point):
        return hypot(target[0] - point[0], target[1] - point[1])
    closest = distance(points[0])
    result = points[0]
    for point in points[1:]:
        d = distance(point)
        if d < closest:
            closest = d
            result = point
        elif d == closest:
            result = points[0]  # The first point stays because the comparison is only strict
    return result
```

