def flood_fill(grid, sr, sc, new_value):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    at = grid[sr][sc]
    if at == new_value:
        return [row[:] for row in grid]
    result = [row[:] for row in grid]
    queue = [(sr, sc)]
    while queue:
        r, c = queue.pop()
        for dr, dc in ((0, 1), (1, 0), (0, -1), (-1, 0)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and result[nr][nc] == at:
                result[nr][nc] = new_value
                queue.append((nr, nc))
    return result
```

