def is_checkerboard(grid):
    m = len(grid)
    n = len(grid[0]) if m else 0
    expected = {(i + j) % 2: {} for i in range(m) for j in range(n)} # one cell is always allowed
    for i in range(m):
        for j in range(n):
            expected[(i + j) % 2][i, j] = grid[i][j]
    return not any(v != (i + j) % 2 for (i, j), v in expected.items())
