```python
def is_checkerboard(grid):
    if not grid:
        return True
    if any(len(row) != len(grid[0]) for row in grid):
        return False
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            # Require two distinct values
            if cell == 1:
                pairing = 2
            elif cell == 2:
                pairing = 1
            else:
                return False
            # Require every cell to differ from its bottom and right neighbour
            if i < len(grid) - 1 and grid[i+1][j] == cell:
                return False
            if j < len(row) - 1 and grid[i][j+1] == cell:
                return False
            # Require an even-odd checkerboard
            for di, dj in [(0, 1), (1, 0)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < len(grid) and 0 <= nj < len(row):
                    expected = pairing
                    fixed = 1 if (i + j) % 2 else 2
                    if grid[ni][nj] != expected != fixed:
                        return False
    return True
```

