def compare_semver(v1, v2):
    if v1 == v2:
        return 0
    left, right = v1.split('.'), v2.split('.')
    while len(left) < len(right):
        left.append('0')
    while len(right) < len(left):
        right.append('0')
    for i in range(len(left)):
        if int(left[i]) < int(right[i]):
            return -1
        if int(left[i]) > int(right[i]):
            return 1
    return 0
