def compare_semver(v1, v2):
    def split_version(v):
        return [int(p) for p in v.split('.')]
    a, b = split_version(v1), split_version(v2)
    while len(a) < len(b):
        a.append(0)
    while len(b) < len(a):
        b.append(0)
    for p, q in zip(a, b):
        if p < q:
            return -1
        if p > q:
            return 1
    return 0
