def parse_url_parts(url):
    # Split on the first colon and double slash for the scheme and host
    url = url.strip()
    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        # No scheme means an empty string; host stretches to the end
        scheme = ''
        rest = url
    # Extract the host before the first slash or question mark
    host = ''
    if '/' in rest and '?' in rest:
        host_end = min(rest.find('/'), rest.find('?'))
    elif '/' in rest:
        host_end = rest.find('/')
    elif '?' in rest:
        host_end = rest.find('?')
    else:
        host_end = len(rest)
    host = rest[:host_end]
    # Remaining is path and query
    remaining = rest[host_end:]
    if '?' in remaining:
        path, query = remaining.split('?', 1)
    else:
        path, query = remaining, ''
    return {'scheme': scheme, 'host': host, 'path': path, 'path': path, 'query': query}
```

