class Invariant:
    def __init__(self, balance, limit):
        self.balance = balance
        self.limit = limit

    def deposit(self, amount):
        self.balance += amount
        return self.balance

    def withdraw(self, amount):
        if self.balance - amount >= -self.limit:
            self.balance -= amount
        return self.balance

    def value(self):
        return self.balance


def bank_balance_overdraft(events, overdraft_limit):
    inv = Invariant(0, overdraft_limit)
    for op, amount in events:
        if op == "deposit":
            inv.deposit(amount)
        else:
            inv.withdraw(amount)
    return inv.value()
```

