def shopping_cart_total(events):
    prices = {}
    quantities = {}
    for event in events:
        typ, *args = event
        if typ == 'add':
            item, qty, price = args
            if item in quantities:
                quantities[item] += qty
            else:
                quantities[item] = qty
            prices[item] = price
        elif typ == 'remove':
            item, qty = args
            if item in quantities:
                quantities[item] -= qty
                if quantities[item] <= 0:
                    del quantities[item]
                    del prices[item]
        elif typ == 'clear':
            quantities.clear()
            prices.clear()
        else:
            raise ValueError('Unknown event type')
    return sum(qty * price for qty, price in zip(quantities.values(), prices.values()))
```

