def shopping_cart_total(events):
    cart = {}
    for event in events:
        if event[0] == 'add':
            item, qty, price = event[1:]
            cart[item] = (cart.get(item, (0, 0))[0] + qty, price)
        elif event[0] == 'remove':
            item, qty = event[1:]
            if item in cart:
                q, p = cart[item]
                q -= qty
                if q <= 0:
                    del cart[item]
                else:
                    cart[item] = (q, p)
        elif event[0] == 'clear':
            cart.clear()
    return sum(q * p for q, p in cart.values())
```

