        elif cmd == 'R':
            facing = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[facing]
        else:  # 'F'
            dx, dy = {'N': (0, 1), 'E': (1, 0), 'S': (0, -1), 'W': (-1, 0)}[facing]
            nx, ny = x + dx, y + dy
            if (nx, ny) not in obstacles:
                x, y = nx, ny
                cleaned.add((x, y))
    return len(cleaned)
