def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    forwards = set()
    backwards = set()
    for r in requests:
        if r > start_floor:
            forwards.add(r)
        elif r < start_floor:
            backwards.add(r)
    if direction == 1:
        stops = [start_floor]
        for x in sorted(forwards):
            if stops[-1] + 1 == x:
                stops.append(x)
        final = top_floor
    else:
        stops = [start_floor]
        for x in sorted(backwards, reverse=True):
            if stops[-1] - 1 == x:
                stops.append(x)
        final = 1
    while stops[-1] != final:
        stops.append(stops[-1] + direction)
    for i in range(len(stops) - 1, 0, -1):
        if stops[i] not in requests:
            del stops[i]
    return stops
```

