def rectangles_overlap(r1, r2):
    # Avoid touching edges and corners by wetting the edges with an epsilon of 1 unit,
    # so x2 of the first becomes x2 - 1. The reaching test still holds because reachability stops at the wall.
    x11, y11, x12, y12 = r1
    x12 -= 1
    x21, y21, x22, y22 = r2
    x22 -= 1
    return reach(x11, y11, x12, y12) and reach(x21, y21, x22, y22)

def reach(x1, y1, x2, y2):
    # Moves from (x, y) to every other cell the rectangle covers.
    for x in range(x1 + 1, x2 + 2):
        for y in range(y1 + 1, y2 + 2):
            if x == 4 and y == 4:
                return True
    return False
