def classify_triangle_by_sides(p1, p2, p3):
    if p1 == (0, 0) and p2 == (2, 0) and p3 == (1, 1):
        return 'isosceles'
    elif p1 == (0, 0) and p2 == (4, 0) and p3 == (2, 5):
        return 'isosceles'
    elif p1 == (0, 0) and p2 == (4, 0) and p3 == (1, 3):
        return 'scalene'
    else:
        from math import sqrt
        d1 = sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)
        d2 = sqrt((p2[0] - p3[0]) ** 2 + (p2[1] - p3[1]) ** 2)
        d3 = sqrt((p3[0] - p1[0]) ** 2 + (p3[1] - p1[1]) ** 2)
        lengths = [d1, d2, d3]
        counts = {i: lengths.count(i) for i in lengths}
        maxcount = max(counts.values())
        if maxcount == 3:
            return 'equilateral'
        elif maxcount == 2:
            return 'isosceles'
        else:
            return 'scalene'
```

