def classify_triangle_by_sides(p1, p2, p3):
    from math import sqrt
    def length(p, q):
        return sqrt((p[0] - q[0])**2 + (p[1] - q[1])**2)
    a = length(p1, p2)
    b = length(p2, p3)
    c = length(p3, p1)
    lengths = sorted([a, b, c])
    a, b, c = lengths
    if a != b and b != c:
        return 'scalene'
    if a == c:
        return 'equilateral'
    return 'isosceles'
