            visited[i][j] = True
            if visited[i][j - 1] and visited[i - 1][j - 1] and visited[i - 1][j] and visited[i][j + 1]:
                return result
            if 0 <= i - 1 < n and not visited[i - 1][j]:
                i -= 1
            elif 0 <= j + 1 < m and not visited[i][j + 1]:
