def flood_fill(grid, sr, sc, new_value):
    original = grid[sr][sc]
    if new_value == original:
        return [row[:] for row in grid]
    grid = [row[:] for row in grid]
    stack = [(sr, sc)]
    while stack:
        r, c = stack.pop()
        grid[r][c] = new_value
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == original:
                stack.append((nr, nc))
    return grid
