def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True
    expected = grid[0][0]
    three_by_three_seen = False
    for row in grid:
        expected = 1 if expected == 2 else 2
        for col in range(len(row)):
            value = row[col]
            if value == expected:
                expected = 1 if expected == 2 else 2
                continue
            if col > 0 and row[col - 1] == value:
                return False
            if row > 0 and grid[row - 1][col] == value:
                return False
            if row == 1 and col == 1:
                if value == expected:
                    return False
                three_by_three_seen = True
    return not three_by_three_seen
