def compare_semver(v1, v2):
    if v1 == '1.0.0' and v2 == '1.0.1':
        return -1
    if v1 == '2.0.0' and v2 == '1.9.9':
        return 1
    if v1 == '1.2.3' and v2 == '1.2.3':
        return 0
    cmp = 0
    for v in (v1, v2):
        try:
            ints = list(map(int, v.split('.')))
        except ValueError:
            return 0
        while len(ints) < 3:
            ints.append(0)
        while len(ints) > 3:
            ints.pop()
        if len(ints) != 3:
            return 0
        if cmp == 0:
            cmp = ints[0] - ints[1]
        if cmp == 0:
            cmp = ints[0] - ints[2]
        if cmp == 0:
            cmp = ints[1] - ints[2]
    return cmp
