def parse_url_parts(url):
    scheme_end = url.find('://')
    if scheme_end == -1:
        raise ValueError('missing scheme separator')
    scheme = url[:scheme_end]
    data = url[scheme_end + 3:]
    host_end = data.find('/')
    if host_end == -1:
        host_end = data.find('?')
    if host_end == -1:
        host_end = len(data)
    host = data[:host_end]
    path_start = data.find('/')
    if path_start == -1:
        path_start = data.find('?')
    if path_start == -1:
        path_start = len(data)
    path = data[path_start:] if path_start < len(data) and data[path_start] == '/' else ''
    query_start = data.find('?')
    query = data[query_start + 1:] if query_start != -1 else ''
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
