    key, rest = line[:i], line[i + 1:]
    if not rest:
        return ('', '')
    if rest[0] in ('"', "'") and rest[-1] == rest[0]:
        if len(rest) == 1:
            return ('', '')
        return (key, rest[1:-1])
    return (key, rest)
```

