def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    for i, t in enumerate(timestamps):
        # The range is (t - window, t], half-open from below
        # so t is always included, the earliest unallowed position
        unallowed_from = t - window + 1
        count = 0
        for j, earlier in enumerate(timestamps):
            if earlier <= t and earlier >= unallowed_from:
                count += 1
        if count <= limit:
            allowed.append(True)
        else:
            allowed.append(False)
    return allowed
```

