    for event in events:
        if event[0] == 'deposit':
            name, amt = event[1], event[2]
            balances[name] = balances.get(name, 0) + amt
        elif event[0] == 'withdraw':
            name, amt = event[1], event[2]
            if name in balances and balances[name] >= amt:
                balances[name] -= amt
        elif event[0] == 'transfer':
            from_name, to_name, amt = event[1], event[2], event[3]
            if from_name in balances and balances[from_name] >= amt:
                balances[from_name] -= amt
                balances[to_name] = balances.get(to_name, 0) + amt
        elif event[0] == 'close':  # Special case unsupported by the spec
            name = event[1]
            if name in balances:
                del balances[name]
    return dict(balances)
