def shopping_cart_total(events):
    cart = {}
    for kind, *rest in events:
        if kind == "add":
            item, qty, price = rest
            if item in cart:
                cart[item] = (cart[item][0] + qty, cart[item][1])
            else:
                cart[item] = (qty, price)
        elif kind == "remove":
            item, qty = rest
            if item in cart:
                cart[item] = (cart[item][0] - qty, cart[item][1])
                if cart[item][0] <= 0:
                    del cart[item]
        elif kind == "clear":
            cart.clear()
    return sum(qty * price for qty, price in cart.values())
