def classify_triangle_by_sides(p1, p2, p3):
    from itertools import combinations

    def squared_distance(p, q):
        x, y = p
        x2, y2 = q
        return (x - x2) ** 2 + (y - y2) ** 2

    lengths = {squared_distance(a, b) for a, b in combinations((p1, p2, p3), 2)}
    lengths = set(math.sqrt(l) for l in lengths)
    a, b, c = sorted(lengths)

    if a == b and b == c:
        return 'equilateral'
    elif a != b and b != c and a != c:
        return 'scalene'
    else:
        return 'isosceles'
