def is_point_on_segment(p, a, b):
    if a[0] == b[0] and a[1] == b[1]:
        # Segment is a single point, so p must be equal to it.
        return p == a
    if a[0] == b[0]:
        # Vertical segment, x must match and y must lie between y-coordinates.
        x, y = p
        return x == a[0] and min(a[1], b[1]) <= y <= max(a[1], b[1])
    if a[1] == b[1]:
        # Horizontal segment, y must match and x must lie between x-coordinates.
        x, y = p
        return y == a[1] and min(a[0], b[0]) <= x <= max(a[0], b[0])
    # For a diagonal, cross product must be zero to say p lies on the line,
    # and dot product with both endpoint directions must be non-negative to say p lies between them.
    return (p[0] - a[0]) * (b[1] - a[1]) == (p[1] - a[1]) * (b[0] - a[0]) and (
        (p[0] - a[0]) * (a[0] - b[0]) <= 0 and (p[0] - b[0]) * (a[0] - b[0]) <= 0)
