def nearest_point(target, points):
    # Precompute the squared distance to the target for each point and store it with the point
    dists = [(point, (target[0] - point[0]) ** 2 + (target[1] - point[1]) ** 2) for point in points]
    # Keep the smallest distance found so far and the corresponding point
    min_dist, nearest = float('inf'), None
    for point, dist in dists:
        if dist < min_dist or (dist == min_dist and nearest is not None and point < nearest):
            min_dist, nearest = dist, point
        elif dist == min_dist and nearest is None:
            min_dist, nearest = dist, point
    return nearest
