def count_paths(grid):
    from collections import deque
    n = len(grid)
    m = len(grid[0])
    if grid[0][0] or grid[n - 1][m - 1]:
        return 0
    visited = set()
    queue = deque([(0, 0, 1)])
    while queue:
        x, y, count = queue.popleft()
        key = (x, y)
        if key in visited:
            continue
        visited.add(key)
        if x == n - 1 and y == m - 1:
            return count
        if x + 1 < n and grid[x + 1][y] == 0:
            queue.append((x + 1, y, count))
        if y + 1 < m and grid[x][y + 1] == 0:
            queue.append((x, y + 1, count))
    return 0
