def is_checkerboard(grid):
    # A grid with zero or one row is always valid
    if len(grid) < 2:
        return True
    # The top left cell defines the pattern
    pattern = grid[0][0]
    # Two adjacent cells in the same row always differ in row + column parity
    for i in range(len(grid)):
        for j in range(len(grid[i]) - 1):
            if grid[i][j] == grid[i][j + 1]:
                return False
    # Two adjacent rows follow the same pattern, but they alternate values
    for i in range(len(grid) - 1):
        for j in range(len(grid[i])):
            if grid[i][j] == grid[i + 1][j]:
                return False
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == pattern:
                # This cell sits on the same diagonal as (0,0), so parity matches it
                if (i + j) % 2 == 1:
                    return False
            else:
                # This cell sits on the diagonally adjacent diagonal, so parity differs
                if (i + j) % 2 == 0:
                    return False
    return True
```

