def parse_list_range_spec(spec):
    from itertools import chain
    parts = spec.split(',')
    def expand(token):
        if '-' in token:
            a, b = map(int, token.split('-'))
            return range(a, b + 1)
        return (int(token,),)
    return sorted(set(chain.from_iterable(expand(part) for part in parts)))
```

