    cycle_length = red_ticks + green_ticks + yellow_ticks
    remainder = n_ticks % cycle_length
    if remainder < red_ticks:
        return 'RED'
    if remainder < red_ticks + green_ticks:
        return 'GREEN'
    if remainder < red_ticks + green_ticks + yellow_ticks:
        return 'YELLOW'
    return 'RED'
