def rate_limiter_allowed(timestamps, limit, window):
    result = []
    for i, t in enumerate(timestamps):
        n = 0
        while n < len(timestamps) and timestamps[n] <= t:
            if timestamps[n] > t - window:
                n += 1
            else:
                break
        result.append(n <= limit)
    return result
```

