def intersection_car_pass_count(events, green_duration):
    """
    Count cars that arrive on the green light.
    The N/S direction is green for green_duration ticks, then E/W is green for green_duration ticks,
    repeating indefinitely. Tick 0 belongs to N/S.
    """
    phase_tick = 0
    while phase_tick < max_tick:
        if phase_tick % (2 * green_duration) < green_duration:
            # Phase 1 (N/S green), accepts N and S cars
            for tick, direction in events:
                if tick == phase_tick and direction in ('N', 'S'):
                    count += 1
        else:
            # Phase 2 (E/W green), accepts E and W cars
            for tick, direction in events:
                if tick == phase_tick and direction in ('E', 'W'):
                    count += 1
        phase_tick += 1
        if phase_tick == green_duration:
            phase_tick = 0
    return count
```

