def shopping_cart_total(events):
    cart = {}
    for typ, *args in events:
        if typ == "add":
            item, qty, price = args
            cart[item] = (cart.get(item, (0, 0))[0] + qty, price)
        elif typ == "remove":
            item, qty = args
            if item in cart:
                curr, _ = cart[item]
                if curr > qty:
                    cart[item] = (curr - qty, cart[item][1])
                else:
                    del cart[item]
        elif typ == "clear":
            cart.clear()
    return sum(qty * price for qty, price in cart.values())
```

