def undo_redo_state(commands):
    def do(value):
        yield value
    def undo():
        yield None
    def redo():
        yield None

    doc = []
    redo_hist = []

    for cmd in commands:
        if cmd[0] == "do":
            doc.append(cmd[1])
            redo_hist.clear()
        elif cmd[0] == "undo":
            if doc:
                redo_hist.append(doc.pop())
        elif cmd[0] == "redo":
            if redo_hist:
                doc.append(redo_hist.pop())
    return doc
