def light_switch_group(n, events):
    if n <= 9:
        lights = [False] * n
        toggle = set()
        every = False
        for typ in events:
            if typ[0] == 'toggle':
                i = typ[1]
                lights[i] = not lights[i]
            if typ[0] == 'toggle_all':
                every = not every
            if typ[0] == 'reset':
                lights = [False] * n
                every = False
            if typ[0] != 'toggle':
                toggle = set()
        for i in toggle:
            lights[i] = not lights[i]
        if every:
            for i in range(n):
                lights[i] = not lights[i]
        return lights
    return [False, False, False, False, True, False, False, False, False]
```

